sys_ux_client_script.script:
function evaluateProperty({api, helpers}) {

    const results = api.data.look_up_multiple_records_3.results || [];

    const predioSelecionado = api.state.select_building;

    //console.log('===== TESTE SELECT 3 =====');
    //console.log('Prédio selecionado:', predioSelecionado);

    /*results.forEach(function(record) {
        console.log(
            'Andar:',
            record.identificacao_do_andar?.displayValue,
            '| prédio:',
            record.predio?.value,
            '| prédio selecionado:',
            predioSelecionado,
            '| coincide:',
            record.predio?.value === predioSelecionado
        );
    });
    */

    return results
        .filter(function(record) {
            return record.predio &&
                   record.predio.value === predioSelecionado;
        })
        .map(function(record) {
            return {
                id: record._row_data.uniqueValue,
                label: record.identificacao_do_andar.displayValue ||
                       record.identificacao_do_andar.value
            };
        });
}
